const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Use the World Database on Protected Areas to get the refuge boundary.
    const wdpa = ee.ImageCollection('WCMC/WDPA/current/polygons');
    const refuge = wdpa.filter(ee.Filter.eq('NAME', 'Isles Dernieres Barrier Islands Refuge')).first().geometry();

    const startYear = 2000;
    const endYear = 2024;
    const startDate1 = ee.Date.fromYMD(startYear, 1, 1);
    const endDate1 = ee.Date.fromYMD(startYear, 12, 31);
    const startDate2 = ee.Date.fromYMD(endYear - 1, 1, 1); // Use 2023-2024 for a good composite
    const endDate2 = ee.Date.fromYMD(endYear, 12, 31);

    // 2. Data Acquisition & Processing
    function maskL8sr(image) {
        // Bit 3 is cloud shadow, bit 4 is cloud.
        const cloudShadowBitMask = (1 << 3);
        const cloudsBitMask = (1 << 4);
        const qa = image.select('QA_PIXEL');
        // Both flags should be set to zero, indicating clear conditions.
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                       .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
        return image.updateMask(mask);
    }

    function maskL457sr(image) {
        const qa = image.select('QA_PIXEL');
        // Bit 4 is cloud.
        const cloud = qa.bitwiseAnd(1 << 4);
        return image.updateMask(cloud.not());
    }

    const getLandArea = (year, startDate, endDate, sensor) => {
        let collection;
        if (sensor === 'L7') {
            collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
                .filterBounds(refuge)
                .filterDate(startDate, endDate)
                .map(maskL457sr);
        } else { // L8/L9
            const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').map(maskL8sr);
            const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').map(maskL8sr);
            collection = ee.ImageCollection(l8.merge(l9))
                .filterBounds(refuge)
                .filterDate(startDate, endDate);
        }

        if (collection.size().getInfo() === 0) {
            return {area: null, images: 0};
        }

        const image = collection.median();

        // Calculate MNDWI: (Green - SWIR1) / (Green + SWIR1)
        // L7 bands: SR_B2 (Green), SR_B5 (SWIR1)
        // L8/9 bands: SR_B3 (Green), SR_B6 (SWIR1)
        const greenBand = sensor === 'L7' ? 'SR_B2' : 'SR_B3';
        const swir1Band = sensor === 'L7' ? 'SR_B5' : 'SR_B6';

        const mndwi = image.normalizedDifference([greenBand, swir1Band]).rename('mndwi');

        // Land is where MNDWI is less than 0
        const land = mndwi.lt(0);

        // Calculate the area of land pixels
        const landAreaImage = land.multiply(ee.Image.pixelArea());

        const stats = landAreaImage.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: refuge,
            scale: 30, // Native Landsat resolution
            maxPixels: 1e9
        });

        const landAreaSqKm = ee.Number(stats.get('mndwi')).divide(1e6);
        return {area: landAreaSqKm.getInfo(), images: collection.size().getInfo()};
    };

    // 3. Calculation
    const period1_data = getLandArea(startYear, startDate1, endDate1, 'L7');
    const period2_data = getLandArea(endYear, startDate2, endDate2, 'L8L9');

    // 4. Validation & Final Answer
    console.log(`Image count for ${startYear}: ${period1_data.images}`);
    console.log(`Image count for ${endYear - 1}-${endYear}: ${period2_data.images}`);

    if (period1_data.images === 0 || period2_data.images === 0) {
        console.log("Evidence: No images found for one or both periods.");
        console.log("C1");
        return;
    }

    const landArea2000 = period1_data.area;
    const landArea2024 = period2_data.area;

    if (landArea2000 === null || landArea2024 === null) {
        console.log("Evidence: Calculation failed, could not determine area.");
        console.log("C3");
        return;
    }

    if (landArea2000 === 0) {
        console.log(`Evidence: Initial land area in ${startYear} was zero.`);
        console.log("C2");
        return;
    }

    const areaLost = landArea2000 - landArea2024;
    const percentageLost = (areaLost / landArea2000) * 100;

    console.log(`Land Area in ${startYear} (sq km): ${landArea2000.toFixed(2)}`);
    console.log(`Land Area in ${endYear} (sq km): ${landArea2024.toFixed(2)}`);
    console.log(`Percentage of land area lost: ${percentageLost.toFixed(2)}%`);

    if (percentageLost > 50) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
